public class InstanceVariableDefaults {
    private int defaultInt;
    private double defaultDouble;
    private boolean defaultBoolean;
    private String defaultReference;

    public void printDefaults() {
        System.out.println("int: " + defaultInt);         // Prints 0
        System.out.println("double: " + defaultDouble);   // Prints 0.0
        System.out.println("boolean: " + defaultBoolean); // Prints false
        System.out.println("String: " + defaultReference); // Prints null
    }
}
